import{_ as t,o,c as r,ag as a}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Week 9 — APIs & Secrets","description":"","frontmatter":{"source":"weeks/09-apis-and-secrets/README.md"},"headers":[],"relativePath":"weeks/09-apis-and-secrets/index.md","filePath":"weeks/09-apis-and-secrets/index.md"}'),s={name:"weeks/09-apis-and-secrets/index.md"};function i(n,e,d,h,l,c){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="week-9--apis--secrets" tabindex="-1">Week 9 — APIs &amp; Secrets <a class="header-anchor" href="#week-9--apis--secrets" aria-label="Permalink to &quot;Week 9 — APIs &amp; Secrets&quot;">​</a></h1><blockquote><p>The browser is public; secrets live on the server.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before Studio A</strong> (≤30 min)</td><td>Read this page and the &quot;Requests and responses&quot; part of <a href="./../../resources/web-basics.html#requests-and-responses-http">How the Web Works</a>. Create two free accounts: a <strong>personal</strong> Google account for a Gemini API key (18+) and a Groq account (your fallback provider). No card needed for either</td></tr><tr><td><strong>Studio A</strong></td><td>Recap · talk: requests, JSON, APIs, keys and the browser/server boundary · live demo: finding a leaked key in 60 seconds · lab: make your micro-app repository, trace one request through its code yourself, put a free key in <code>.env</code> · checkpoint share</td></tr><tr><td><strong>Studio B</strong></td><td>Show and tell · lab: run it in your Codespace, call your endpoint without the page, make it yours (its job and its page) · project time · exit ticket</td></tr><tr><td><strong>Due before next week&#39;s Studio A</strong></td><td>Default 11:59 pm the night before. Your micro-app does its own job in your Codespace, committed and synced (no <code>.env</code> on GitHub) · your own input limit, each error tried on purpose · a first draft of your capstone pitch · <code>PROMPTS.md</code> · reflection on Canvas (🔴 AI off)</td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: Copilot Chat in Ask mode for the system prompt and the page · 🟡 AI limited: the code trace (you first; then Ask mode for lines you can&#39;t explain), the pitch draft (AI may critique it; you write it) · 🔴 AI off: any step with <code>.env</code> open, the reflection, the exit ticket. <strong>Never:</strong> a key in any AI tool</td></tr><tr><td><strong>Must read</strong></td><td>This page, <a href="./lab.html">Week 9 Lab — Run the AI micro-app and make it yours</a>, <a href="./homework.html">Week 9 Homework — Make the micro-app yours, start your pitch</a></td></tr><tr><td><strong>Look up when needed</strong></td><td><a href="https://github.com/Boyu-Zhang-UOI/vc101-micro-app-starter/blob/main/README.md" target="_blank" rel="noreferrer">AI micro-app starter</a> · <a href="./../../projects/ai-micro-app.html">AI Micro-app brief</a> · <a href="./../../resources/troubleshooting.html#my-api-call-returns-an-error">Troubleshooting: my API call returns an error</a> · <a href="./../../TOOLS.html">Tool Handout</a> · <a href="./../../resources/glossary.html">Glossary</a></td></tr><tr><td><strong>Minimum to keep up</strong></td><td>Your micro-app answers a question in your Codespace, with your own key, and <code>git status</code> doesn&#39;t list <code>.env</code>. Week 10 puts exactly that on the web</td></tr><tr><td><strong>Time</strong></td><td>Studios 2.5 h · outside about 6 h: prep 30 min, homework core about 3 h, project build time about 2 h, <code>PROMPTS.md</code> and the reflection about 30 min</td></tr></tbody></table><p>Weeks 9 and 10 build one project, the <a href="./../../projects/ai-micro-app.html">AI micro-app</a>: this week it runs in your Codespace; in <a href="./../10-servers-and-deployment/">week 10</a> it goes live.</p><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Describe an HTTP request and response (method, address, headers, body, status code) and read one in DevTools.</li><li>Explain what an API, an endpoint and JSON are, and how JSON differs from a Python dictionary.</li><li>Say which parts of a web app are public (the browser) and which are private (the server), and why a secret key never goes to the browser, into git or into an AI chat.</li><li>Keep a secret key in an environment variable, in a <code>.env</code> file that <code>.gitignore</code> keeps out of git.</li><li>Trace one request through the starter&#39;s code, from the click to the AI provider and back.</li><li>Explain why a public endpoint checks its input on the server, and what a rate limit (status <code>429</code>) is.</li><li>Tell a secret key from a publishable key.</li><li>Give the app a new job by rewriting its system prompt, judged against checks you wrote first.</li></ol><h2 id="before-class" tabindex="-1">Before class <a class="header-anchor" href="#before-class" aria-label="Permalink to &quot;Before class&quot;">​</a></h2><ul><li>☐ You can open a Codespace and use its terminal (<a href="./../../setup/codespaces.html">GitHub Codespaces</a>).</li><li>☐ A <strong>personal</strong> Google account (not a school one) for a Gemini API key, if you are 18 or over. Under 18, or in the EEA, UK or Switzerland? Your instructor gives you a different provider.</li><li>☐ A free <strong>Groq</strong> account (console.groq.com) as a fallback.</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>This week you handle your first real secret. Rule 2 of the <a href="./../../setup/safety-contract.html#2-i-never-paste-secrets-or-other-peoples-data-into-an-ai-tool">Safety Contract</a> applies from now on: <strong>never paste an API key into an AI tool</strong>, a chat, an issue or a commit. Secret keys go in <code>.env</code> (and, from week 10, in Vercel&#39;s settings) and nowhere else.</p></div><h2 id="studio-agenda" tabindex="-1">Studio agenda <a class="header-anchor" href="#studio-agenda" aria-label="Permalink to &quot;Studio agenda&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Studio</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Studio A — Learn &amp; build</strong></td><td>Recap · concept talk (<a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-09.html" target="_blank" rel="noreferrer">slides</a>) · live demo · <a href="./lab.html#studio-a--run-it-with-your-own-key-75-min">lab</a>: make your repository, trace one request, add your key · checkpoint share</td></tr><tr><td><strong>Studio B — Workshop</strong></td><td>Show and tell · <a href="./lab.html#studio-b--make-it-yours-75-min">lab</a>: run it, call it the way a stranger would, make it yours · project time · exit ticket</td></tr></tbody></table><h2 id="materials" tabindex="-1">Materials <a class="header-anchor" href="#materials" aria-label="Permalink to &quot;Materials&quot;">​</a></h2><ul><li><a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-09.html" target="_blank" rel="noreferrer">Slides</a> · <a href="./lab.html">Lab</a> (with a troubleshooting table) · <a href="./homework.html">Homework</a></li><li><a href="https://github.com/Boyu-Zhang-UOI/vc101-micro-app-starter" target="_blank" rel="noreferrer">AI micro-app starter</a>: the page, the server route and its tests (<a href="https://github.com/Boyu-Zhang-UOI/vc101-micro-app-starter/blob/main/README.md" target="_blank" rel="noreferrer">starter README</a>)</li><li>Shared files: the <a href="./../../projects/ai-micro-app.html">AI Micro-app brief</a>, the <a href="./../../templates/PROMPTS.html">PROMPTS.md template</a>, <a href="./../../resources/safe-loop.html">The Safe Loop</a></li><li>Glossary: <a href="./../../resources/glossary.html#http">HTTP</a>, <a href="./../../resources/glossary.html#json">JSON</a>, <a href="./../../resources/glossary.html#api">API</a>, <a href="./../../resources/glossary.html#api-key">API key</a>, <a href="./../../resources/glossary.html#environment-variable">environment variable</a>, <a href="./../../resources/glossary.html#rate-limit">rate limit</a>, <a href="./../../resources/glossary.html#publishable-key">publishable key</a></li></ul><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><p>If you are working through this week on your own, read this section, then do the <a href="./lab.html">lab</a>.</p><h3 id="requests-responses-and-apis" tabindex="-1">Requests, responses and APIs <a class="header-anchor" href="#requests-responses-and-apis" aria-label="Permalink to &quot;Requests, responses and APIs&quot;">​</a></h3><p>The browser asks another computer for something with an <strong>HTTP request</strong>: a method (<code>GET</code> to fetch, <code>POST</code> to send), an address, headers and sometimes a body. It gets back a <strong>response</strong> with a <strong>status code</strong> (<code>200</code> OK, <code>400</code> bad request, <code>401</code> not allowed, <code>429</code> too many requests, <code>500</code> server error) and a body, usually <strong>JSON</strong> such as <code>{&quot;reply&quot;: &quot;Hello&quot;}</code>. JSON looks like a Python dictionary but is text with stricter rules: double quotes only, and <code>true</code>, <code>false</code>, <code>null</code> for <code>True</code>, <code>False</code>, <code>None</code>. An <strong>API</strong> is the set of requests a service accepts; each address that does one job is an <strong>endpoint</strong>. <em>The menu is the API, your order is the request, the kitchen you never see is the server.</em></p><h3 id="the-browser-is-public" tabindex="-1">The browser is public <a class="header-anchor" href="#the-browser-is-public" aria-label="Permalink to &quot;The browser is public&quot;">​</a></h3><p>Everything sent to the browser (HTML, CSS, JavaScript, every request and response) can be read by anyone with DevTools. A key &quot;hidden&quot; in JavaScript is a published key. So a secret key stays on a <strong>server</strong>, and the browser talks only to your server: the <a href="./../../resources/web-basics.html#the-trust-boundary">trust boundary</a>.</p><h3 id="an-api-key-is-a-password-with-a-bill-attached" tabindex="-1">An API key is a password with a bill attached <a class="header-anchor" href="#an-api-key-is-a-password-with-a-bill-attached" aria-label="Permalink to &quot;An API key is a password with a bill attached&quot;">​</a></h3><p>Anyone who has your <strong>API key</strong> can use your quota or run up your bill. AI-assisted commits leak secrets about twice as often as other commits, about 3.2% versus 1.6% (<a href="https://blog.gitguardian.com/the-state-of-secrets-sprawl-2026/" target="_blank" rel="noreferrer">GitGuardian 2026</a>). Two habits limit the damage (<a href="./../../setup/safety-contract.html#4-i-keep-agents-contained">Safety Contract, rule 4</a>): a key that can spend money has a <strong>hard spending cap</strong> (on our free tiers, simply no payment method on the account), and each key does one job in one project.</p><h3 id="where-secrets-live" tabindex="-1">Where secrets live <a class="header-anchor" href="#where-secrets-live" aria-label="Permalink to &quot;Where secrets live&quot;">​</a></h3><p>In your Codespace the key lives in <strong><code>.env</code></strong>, which the server reads into <strong>environment variables</strong> (settings a program reads when it starts, kept outside the code). <code>.env</code> is listed in <strong><code>.gitignore</code></strong>, so git never commits it; the committed <strong><code>.env.example</code></strong> holds placeholders only. In week 10 the same settings go into Vercel&#39;s settings for the live site.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Not every key is a secret.</strong> Some keys are <em>meant</em> to be public. In week 13 you&#39;ll put Supabase&#39;s <strong>publishable key</strong> in the browser on purpose; it&#39;s safe only because database rules (row-level security) decide what it can do. A <strong>secret</strong> key, like this week&#39;s AI key, never goes near the browser. When in doubt, treat a key as secret and ask.</p></div><h3 id="your-endpoint-is-public-so-the-server-checks-everything" tabindex="-1">Your endpoint is public, so the server checks everything <a class="header-anchor" href="#your-endpoint-is-public-so-the-server-checks-everything" aria-label="Permalink to &quot;Your endpoint is public, so the server checks everything&quot;">​</a></h3><p>Free tiers cap your requests; past the cap you get status <code>429</code>, a <strong>rate limit</strong>. Once live, your <code>/api/ask</code> route can be called by <strong>anyone</strong>, skipping your page, spending your quota. So the server checks every request itself (the page&#39;s checks are only a convenience), and in week 10 you write tests that prove it.</p><h3 id="the-system-prompt-is-product-design" tabindex="-1">The system prompt is product design <a class="header-anchor" href="#the-system-prompt-is-product-design" aria-label="Permalink to &quot;The system prompt is product design&quot;">​</a></h3><p>The same model becomes a recipe helper or a polite-email rewriter depending on its <strong>system prompt</strong>: the hidden instructions your server sends with every question. An AI&#39;s answers vary from run to run, so instead of an automated test you write three checks before you prompt, and judge the result by them.</p><h2 id="understanding-check" tabindex="-1">Understanding check <a class="header-anchor" href="#understanding-check" aria-label="Permalink to &quot;Understanding check&quot;">​</a></h2><p>At the end of Studio B you complete the week 9 exit ticket (🔴 AI off). Expect to <strong>trace one request</strong> from the click to the AI provider and back, say where the key is stored and added, and say what a visitor with DevTools can and cannot see. One question looks back at week 7: a bug you found, and how you narrowed it down. Exit tickets are graded on completion, not correctness.</p><h2 id="homework" tabindex="-1">Homework <a class="header-anchor" href="#homework" aria-label="Permalink to &quot;Homework&quot;">​</a></h2><p>Details and the checklist are in <a href="./homework.html">Week 9 Homework — Make the micro-app yours, start your pitch</a>.</p><ul><li><strong>Core (required):</strong> make the app fully yours and describe it in its README; your own input limit, each error tried on purpose; a capstone pitch draft (🟡 AI limited); <code>PROMPTS.md</code>; the reflection on Canvas (🔴 AI off).</li><li><strong>Stretch (optional):</strong> conversation memory, streaming replies, or a local model with Ollama.</li></ul><p>The micro-app is graded once, at the end of week 10, with the <a href="./../../assessment/rubrics.html#ai-micro-app">AI micro-app rubric</a>.</p><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>What to do</th></tr></thead><tbody><tr><td>Can&#39;t get a Gemini key (under 18, region, school account)</td><td>Use Groq as your primary provider (<a href="./../../TOOLS.html">Tool Handout</a>, Course variants)</td></tr><tr><td>Your provider returns <code>429</code> or is down</td><td>Change the three <code>LLM_</code> settings in <code>.env</code> to Groq or OpenRouter and restart</td></tr><tr><td>Codespaces quota used up</td><td>Stop old codespaces at github.com/codespaces, or use the optional <a href="./../../setup/local-setup.html">local setup</a></td></tr><tr><td>Copilot credits ran out</td><td>Keep going without it: no lab step needs AI (<a href="./../../resources/troubleshooting.html#i-ran-out-of-free-credits">I ran out of free credits</a>)</td></tr></tbody></table><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>MDN, <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Overview" target="_blank" rel="noreferrer">An overview of HTTP</a>: requests, responses and status codes.</li><li>GitGuardian, <a href="https://blog.gitguardian.com/the-state-of-secrets-sprawl-2026/" target="_blank" rel="noreferrer">The State of Secrets Sprawl 2026</a>: how and where secrets leak.</li><li>More readings: the <a href="./../../resources/reading-list.html">Reading List</a>.</li></ul>',40)])])}const m=t(s,[["render",i]]);export{p as __pageData,m as default};
